INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('9cb0e54e-4dbb-53db-b39e-85ec6d9f9dc5','VOCABULARY','N5','水','nước','みず','水を飲みます。','Tôi uống nước.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('4d274b54-4e00-5c17-bfec-2b0bc51b5623','VOCABULARY','N5','大きい','to, lớn','おおきい','大きい家ですね。','Căn nhà lớn nhỉ.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('35432d71-cc44-5440-8944-156c5523a79a','VOCABULARY','N5','友達','bạn bè','ともだち','友達と話します。','Tôi nói chuyện với bạn.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('8d4cc956-9c9d-57e3-8eaf-52cc88e2052a','VOCABULARY','N4','約束','lời hứa; cuộc hẹn','やくそく','約束を守ります。','Tôi giữ lời hứa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('d736328a-0f03-5ac6-83b0-6fe465d30e4e','VOCABULARY','N4','準備','chuẩn bị','じゅんび','旅行の準備をしています。','Tôi đang chuẩn bị cho chuyến đi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('6f90a2ce-7e48-52c5-a7ab-e342dbd2b893','VOCABULARY','N4','間に合う','kịp giờ','まにあう','電車に間に合いました。','Tôi đã kịp chuyến tàu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('185b931b-8628-5f1c-921c-2a11b69c525d','VOCABULARY','N4','必要','cần thiết','ひつよう','予約が必要です。','Cần phải đặt trước.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('a9849aa1-8648-5a9f-a132-23cb85cdcd45','VOCABULARY','N4','探す','tìm kiếm','さがす','鍵を探しています。','Tôi đang tìm chìa khóa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('91741f76-0f87-58e7-9600-b2e2f098f47d','VOCABULARY','N3','見積もり','báo giá; ước tính','みつもり','見積もりを確認してください。','Vui lòng kiểm tra báo giá.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('f66068ca-8655-5b2b-84bb-44eca1fd7bf9','VOCABULARY','N3','後回し','để sau, trì hoãn','あとまわし','この作業は後回しにします。','Tôi sẽ để công việc này làm sau.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('c10cb3ad-b6ec-5970-a156-f8b5a9395cf7','VOCABULARY','N3','見落とす','bỏ sót','みおとす','小さなミスを見落としました。','Tôi đã bỏ sót một lỗi nhỏ.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('faf66861-2d85-5723-8975-6a8405ab4df1','VOCABULARY','N3','確認','xác nhận, kiểm tra','かくにん','内容を確認します。','Tôi sẽ kiểm tra nội dung.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('d342b9ef-8268-57bc-aedf-fd94bf0c6c90','VOCABULARY','N3','努力','nỗ lực','どりょく','毎日努力しています。','Tôi nỗ lực mỗi ngày.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('2a361b48-6600-51d1-ac5a-091e24f81188','VOCABULARY','N2','改善','cải thiện','かいぜん','作業の流れを改善します。','Tôi sẽ cải thiện quy trình làm việc.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('9c78b63d-f21e-5413-8583-36501dff3679','VOCABULARY','N2','把握','nắm bắt','はあく','状況を把握しました。','Tôi đã nắm được tình hình.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('7e92ef94-c9ae-5045-a1d9-9d2682369188','VOCABULARY','N2','傾向','xu hướng','けいこう','同じ傾向が見られます。','Có thể thấy xu hướng tương tự.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('3222e116-5930-56f5-b48e-69c30fa6ddc2','VOCABULARY','N2','貢献','đóng góp, cống hiến','こうけん','社会に貢献したいです。','Tôi muốn đóng góp cho xã hội.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('b484abc9-2f04-5ce0-8f9a-f4ae18123018','VOCABULARY','N2','余裕','sự dư dả; thong thả','よゆう','時間に余裕があります。','Tôi có thời gian dư dả.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('100ec733-dc7f-5c46-886f-ecceb0cc4af8','VOCABULARY','N1','捻出','xoay xở để có thời gian, tiền','ねんしゅつ','勉強する時間を捻出します。','Tôi xoay xở dành thời gian học.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('b96ce153-ecad-592e-8cee-78c71c025253','VOCABULARY','N1','由々しい','nghiêm trọng, đáng lo ngại','ゆゆしい','これは由々しい問題です。','Đây là một vấn đề nghiêm trọng.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('00f3992e-4482-570b-9057-dae600fe7ef1','VOCABULARY','N1','顕著','rõ rệt, nổi bật','けんちょ','顕著な変化が見られます。','Có thể thấy sự thay đổi rõ rệt.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('e15965bd-e75b-5935-a2f1-46c9cb231e9c','VOCABULARY','N1','妥協','thỏa hiệp, nhượng bộ','だきょう','品質では妥協しません。','Tôi không thỏa hiệp về chất lượng.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,example_sentence,example_meaning_vi) VALUES('d7ebedff-29e8-515d-a589-a37ace423e32','VOCABULARY','N1','遂行','thực hiện, hoàn thành','すいこう','任務を遂行します。','Tôi sẽ thực hiện nhiệm vụ.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,formation,explanation,example_sentence,example_meaning_vi,extra_examples) VALUES('5d4f4e53-94cc-52ca-8add-e3b9d33eecf3','GRAMMAR','N5','〜たい','muốn làm gì','Vます bỏ ます + たい','Diễn tả mong muốn của người nói. Chia như tính từ đuôi い.','日本へ行きたいです。','Tôi muốn đến Nhật.','日本へ行く → 行きたい') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,formation,explanation,example_sentence,example_meaning_vi,extra_examples) VALUES('2e498aa0-8371-5d22-b4b3-0b78ae21ed59','GRAMMAR','N5','〜てもいい','được phép làm gì','Vて + もいい','Dùng để cho phép hoặc xin phép khi thêm ですか.','ここに座ってもいいですか。','Tôi ngồi ở đây được không?','窓を開けてもいいです。 → Có thể mở cửa sổ.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,formation,explanation,example_sentence,example_meaning_vi,extra_examples) VALUES('c7923e7f-b9ab-50c7-ad9c-a9883b236bb8','GRAMMAR','N4','〜ことがある','đã từng','Vた + ことがある','Diễn tả một trải nghiệm từng có; không dùng để kể một hành động ở thời điểm cụ thể.','日本へ行ったことがあります。','Tôi đã từng đến Nhật.','寿司を作ったことがあります。 → Tôi đã từng làm sushi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,formation,explanation,example_sentence,example_meaning_vi,extra_examples) VALUES('830af056-8769-5cf2-bdb1-03b23dbcee27','GRAMMAR','N4','〜ながら','vừa… vừa…','Vます bỏ ます + ながら','Hai hành động do cùng một chủ thể thực hiện; hành động chính nằm ở vế sau.','音楽を聞きながら勉強します。','Tôi vừa nghe nhạc vừa học.','歩きながら話しました。 → Chúng tôi vừa đi vừa nói chuyện.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,formation,explanation,example_sentence,example_meaning_vi,extra_examples) VALUES('7c5ba982-fc85-5c01-a668-fcd402b44ac1','GRAMMAR','N3','〜ことになる','được quyết định là','V辞書形／Vない + ことになる','Diễn tả quyết định do hoàn cảnh hoặc tập thể, khác với ことにする là chủ thể tự quyết định.','来月から大阪で働くことになりました。','Đã có quyết định là từ tháng sau tôi sẽ làm việc ở Osaka.','会議は延期することになりました。 → Cuộc họp đã được quyết định hoãn lại.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,formation,explanation,example_sentence,example_meaning_vi,extra_examples) VALUES('2ce9ec13-34b0-5ce6-b9ec-ffd65870eba8','GRAMMAR','N3','〜ようにする','cố gắng, tạo thói quen','V辞書形／Vない + ようにする','Nhấn mạnh việc có ý thức thực hiện hoặc tránh một hành động.','毎日日本語を読むようにしています。','Tôi cố gắng đọc tiếng Nhật mỗi ngày.','忘れないようにしてください。 → Hãy chú ý đừng quên.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,formation,explanation,example_sentence,example_meaning_vi,extra_examples) VALUES('96fc569e-40fb-52c0-bd52-001e0decfdc2','GRAMMAR','N2','〜わけではない','không hẳn là','Thể thông thường + わけではない','Phủ định một phần hoặc bác bỏ một cách suy diễn. Với danh từ dùng というわけではない.','日本語が全部わかるわけではありません。','Không phải tôi hiểu hết tiếng Nhật.','嫌いなわけではありません。 → Không phải là tôi ghét.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,formation,explanation,example_sentence,example_meaning_vi,extra_examples) VALUES('3f7db046-c63e-510c-af3e-fcd20d7814a9','GRAMMAR','N2','〜に限らず','không chỉ… mà còn…','N + に限らず','Mở rộng phạm vi nhận định ra các trường hợp khác.','この店は週末に限らず、平日も混んでいます。','Quán này không chỉ cuối tuần mà ngày thường cũng đông.','子供に限らず、大人にも人気です。 → Không chỉ trẻ em, người lớn cũng thích.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,formation,explanation,example_sentence,example_meaning_vi,extra_examples) VALUES('bfa93367-79b8-5e87-84e5-05c6cd3592bf','GRAMMAR','N1','〜に至るまで','đến tận, ngay cả','N + に至るまで','Nhấn mạnh mức độ bao quát đến cả chi tiết hoặc phạm vi cuối cùng.','細部に至るまで確認しました。','Tôi đã kiểm tra đến từng chi tiết.','服装に至るまで同じでした。 → Đến cả trang phục cũng giống nhau.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,formation,explanation,example_sentence,example_meaning_vi,extra_examples) VALUES('3a63ca93-f6ec-5abb-bd04-41842aab1d63','GRAMMAR','N1','〜を余儀なくされる','buộc phải','N + を余儀なくされる','Dùng trong văn viết khi hoàn cảnh bên ngoài buộc chủ thể làm điều không mong muốn.','大雨で計画の変更を余儀なくされました。','Chúng tôi buộc phải thay đổi kế hoạch do mưa lớn.','避難を余儀なくされました。 → Đã bị buộc phải sơ tán.') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,onyomi,kunyomi,stroke_count,extra_examples) VALUES('a698a7d8-f5b7-5a91-b059-01059c9ccb50','KANJI','N5','日','ngày; mặt trời','ニチ・ジツ ひ・か','ニチ・ジツ','ひ・か',4,'日本（にほん）・休日（きゅうじつ）') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,onyomi,kunyomi,stroke_count,extra_examples) VALUES('dda6a2cf-24d3-58be-9261-060980199de4','KANJI','N5','人','người','ジン・ニン ひと','ジン・ニン','ひと',2,'日本人（にほんじん）・一人（ひとり）') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,onyomi,kunyomi,stroke_count,extra_examples) VALUES('997b0bb8-156d-57c3-b7a1-b9be52c66f95','KANJI','N4','食','ăn; thức ăn','ショク・ジキ た.べる・く.う','ショク・ジキ','た.べる・く.う',9,'食べる（たべる）・食事（しょくじ）') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,onyomi,kunyomi,stroke_count,extra_examples) VALUES('29556ea8-e266-55a3-a806-579d82caef10','KANJI','N4','学','học','ガク まな.ぶ','ガク','まな.ぶ',8,'学校（がっこう）・学生（がくせい）') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,onyomi,kunyomi,stroke_count,extra_examples) VALUES('a630f5f2-1b28-5809-b67b-65b289f78dbd','KANJI','N3','約','ước hẹn; khoảng','ヤク ','ヤク','',9,'約束（やくそく）・予約（よやく）') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,onyomi,kunyomi,stroke_count,extra_examples) VALUES('d2e54917-09d8-551a-a402-f81b9268ce63','KANJI','N3','確','chắc chắn','カク たし.か・たし.かめる','カク','たし.か・たし.かめる',15,'確認（かくにん）・正確（せいかく）') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,onyomi,kunyomi,stroke_count,extra_examples) VALUES('2afc01e2-8eda-5a2a-baa0-3aecb0ab5362','KANJI','N2','改','sửa đổi','カイ あらた.める・あらた.まる','カイ','あらた.める・あらた.まる',7,'改善（かいぜん）・改革（かいかく）') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,onyomi,kunyomi,stroke_count,extra_examples) VALUES('8af5fbb0-fe4d-56ea-989c-45ef46f11f30','KANJI','N2','善','thiện; tốt','ゼン よ.い','ゼン','よ.い',12,'善意（ぜんい）・改善（かいぜん）') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,onyomi,kunyomi,stroke_count,extra_examples) VALUES('a148e67f-3367-5653-88ef-f208675d29b6','KANJI','N1','顕','rõ ràng; hiện rõ','ケン ','ケン','',18,'顕著（けんちょ）・顕在（けんざい）') ON CONFLICT (id) DO NOTHING;
INSERT INTO learning_items(id,type,jlpt_level,word,meaning_vi,reading,onyomi,kunyomi,stroke_count,extra_examples) VALUES('d4648ebb-e3a2-5ae1-9f73-5360a4a6f9aa','KANJI','N1','遂','hoàn thành; cuối cùng','スイ と.げる','スイ','と.げる',12,'遂行（すいこう）・成し遂げる（なしとげる）') ON CONFLICT (id) DO NOTHING;
